using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations ---

var notebook = new Notebook();

[Description("Search the web for information on a query. Returns a list of result snippets.")]
string WebSearch([Description("The search query string")] string query)
{
    Console.WriteLine($"  🔍 Searching: \"{query}\"");
    using var client = new HttpClient();
    // Use DuckDuckGo Instant Answer API (no key required)
    var encoded = WebUtility.UrlEncode(query);
    var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
    var json = client.GetStringAsync(url).GetAwaiter().GetResult();
    using var doc = JsonDocument.Parse(json);
    var root = doc.RootElement;

    var results = new List<string>();

    // Abstract / abstract text
    var abs = root.GetProperty("Abstract").GetString();
    if (!string.IsNullOrWhiteSpace(abs))
        results.Add($"[Summary] {abs}");

    // Related topics
    if (root.TryGetProperty("RelatedTopics", out var topics))
    {
        foreach (var topic in topics.EnumerateArray().Take(5))
        {
            if (topic.TryGetProperty("Text", out var text))
                results.Add($"[Related] {text.GetString()}");
        }
    }

    if (results.Count == 0)
        results.Add("No results found. Try rephrasing the query.");

    var output = string.Join("\n", results);
    Console.WriteLine($"  📄 Got {results.Count} result(s)");
    return output;
}

[Description("Save a note to the research notebook for later summarization.")]
string SaveNote(
    [Description("A short label or category for the note")] string title,
    [Description("The content of the note")] string content)
{
    notebook.Add(title, content);
    Console.WriteLine($"  📝 Note saved: \"{title}\"");
    return $"Note '{title}' saved successfully. You now have {notebook.Count} note(s).";
}

[Description("Retrieve all saved notes from the research notebook.")]
string GetNotes()
{
    if (notebook.Count == 0)
        return "The notebook is empty.";

    Console.WriteLine($"  📖 Reading {notebook.Count} note(s)");
    return notebook.ToString();
}

// --- Agent setup ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

var systemPrompt = """
    You are a research agent. Your job is to research a topic the user gives you.

    Workflow:
    1. Break the topic into 2-3 focused search queries.
    2. Use the WebSearch tool to find information for each query.
    3. Use the SaveNote tool to record key findings as you go.
    4. After gathering enough information, use GetNotes to review everything.
    5. Provide a well-structured summary of your findings to the user.

    Be thorough but concise. Cite the information you found.
    """;

// --- Main loop ---

Console.WriteLine("🤖 Research Agent Ready!");
Console.WriteLine("   Enter a topic to research (or 'quit' to exit).\n");

while (true)
{
    Console.Write("Topic> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
    };

    Console.WriteLine("\n⏳ Researching...\n");

    var response = await chatClient.GetResponseAsync(messages, new()
    {
        Tools = [.. tools],
    });

    Console.WriteLine("\n--- Research Summary ---\n");
    Console.WriteLine(response.Text);
    Console.WriteLine("\n------------------------\n");
}

Console.WriteLine("Goodbye!");

// --- Notebook helper ---

class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public int Count => _notes.Count;

    public void Add(string title, string content) => _notes.Add((title, content));

    public void Clear() => _notes.Clear();

    public override string ToString() =>
        string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));
}

